const readThemeVar = (name, fallback) => {
  if (typeof window === 'undefined' || typeof document === 'undefined') {
    return fallback;
  }
  const value = window.getComputedStyle(document.documentElement).getPropertyValue(name).trim();
  return value || fallback;
};

const resolveAccentLightTheme = () => ({
  ...ACCENT_LIGHT_BASE_THEME,
  foreground: readThemeVar('--el-text-color-primary', ACCENT_LIGHT_BASE_THEME.foreground),
  cursor: readThemeVar('--el-color-primary-dark-1', ACCENT_LIGHT_BASE_THEME.cursor),
  selection: readThemeVar('--theme-primary-soft-active-strong', ACCENT_LIGHT_BASE_THEME.selection),
  blue: readThemeVar('--el-color-primary', ACCENT_LIGHT_BASE_THEME.blue),
  brightBlue: readThemeVar('--el-color-primary-dark-1', ACCENT_LIGHT_BASE_THEME.brightBlue),
  cyan: readThemeVar('--theme-primary-icon-color', ACCENT_LIGHT_BASE_THEME.cyan),
  brightCyan: readThemeVar('--theme-primary-icon-hover-color', ACCENT_LIGHT_BASE_THEME.brightCyan),
});

export const getThemeContainerStyle = (name) => {
  if (name === ACCENT_LIGHT_THEME) {
    return {
      backgroundColor: '#ffffff',
      backgroundImage: 'linear-gradient(270deg, var(--el-color-primary-light-9) 0%, var(--el-color-primary-light-9) 98%, #ffffff 100%)',
    };
  }

  return {
    backgroundColor: getTheme(name).background,
  };
};

